// Test of mgc_mm_is, generated by mgc from mm_is.mgc: do not edit, re-run mgc/mgcc.py.

#include <stdint.h>

#include "mgc_mm_is.h"
#include "test.h"

#include "tile.h"
#include "fsync.h"
#include "eventunit.h"

int main(void)
{
    uint32_t hartid = get_hartid();

    mgc_mm_is(x_inp, w_inp, y_inp, M_SIZE, N_SIZE, K_SIZE);

    /* once every tile has finished, each tile checks its share of the rows */
    fsync_init();
    eu_fsync_init(0);
    fsync_sync_global();
    eu_fsync_wait(WFE);

    uint32_t share  = (M_SIZE + NUM_HARTS - 1) / NUM_HARTS;
    uint32_t r_end  = (hartid + 1) * share < M_SIZE ? (hartid + 1) * share : M_SIZE;
    uint32_t errors = 0;
    uint16_t computed, expected, diff;
    for (uint32_t i = hartid * share; i < r_end; i++) {
        for (uint32_t j = 0; j < K_SIZE; j++) {
            computed = *(volatile uint16_t *)(y_inp + (i * K_SIZE + j));
            expected = *(volatile uint16_t *)(z_out + (i * K_SIZE + j));
            diff     = (computed > expected) ? (computed - expected) : (expected - computed);
            if (diff > 0x0011) {
#if EVAL == 1
                printf("Error detected at coordinates[%d][%d]: y_inp=%x z_out=%x\n",
                       i,
                       j,
                       *(volatile uint16_t *)(y_inp + (i * K_SIZE + j)),
                       *(volatile uint16_t *)(z_out + (i * K_SIZE + j)));
#endif
                errors++;
            }
        }
    }
    printf("TILE %d: Number of errors: %d\n", hartid, errors);

    return errors;
}
